    approveDeviceCode: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": components["schemas"]["ApproveDeviceRequest"];
            };
        };
        responses: {
            /** @description Approved. The television's next poll receives a session. */
            204: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            400: components["responses"]["BadRequest"];
            401: components["responses"]["Unauthorized"];
            /** @description No pending authorization carries this code (`DEVICE_CODE_NOT_FOUND`). */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            /** @description The code was already approved, denied or consumed (`DEVICE_CODE_ALREADY_USED`). */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            /** @description The code has expired (`DEVICE_CODE_EXPIRED`). The TV displays a new one on its own. */
            410: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            429: components["responses"]["TooManyRequests"];
        };
    };
    pollDeviceToken: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": components["schemas"]["DeviceTokenRequest"];
            };
        };
        responses: {
            /** @description Approved. The `device_code` is now consumed and cannot be reused. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["AuthSession"];
                };
            };
            /**
             * @description RFC 8628 polling states, carried in `code`:
             *
             *     | `code` | Meaning | TV behaviour |
             *     |---|---|---|
             *     | `AUTHORIZATION_PENDING` | Not approved yet | Keep polling at `interval` |
             *     | `SLOW_DOWN` | Polling too fast | Add 5 s to `interval`, keep polling |
             *     | `ACCESS_DENIED` | The user refused | Stop, show a message |
             *     | `EXPIRED_TOKEN` | The code expired | Request a new code silently |
             *     | `DEVICE_CODE_NOT_FOUND` | Unknown `device_code` | Request a new code |
             */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
        };
    };
